def comps(M, val=5, conn=4):
    M=np.array(M); H,W=M.shape; lab=-np.ones((H,W),int); n=0; res=[]
    offs=[(1,0),(-1,0),(0,1),(0,-1)] if conn==4 else [(a,b) for a in(-1,0,1) for b in(-1,0,1) if (a,b)!=(0,0)]
    for r in range(H):
        for c in range(W):
            if M[r,c]==val and lab[r,c]<0:
                dq=deque([(r,c)]); lab[r,c]=n; comp=[]
                while dq:
                    a,b=dq.popleft(); comp.append((a,b))
                    for dr,dc in offs:
                        nr,nc=a+dr,b+dc
                        if 0<=nr<H and 0<=nc<W and M[nr,nc]==val and lab[nr,nc]<0:
                            lab[nr,nc]=n; dq.append((nr,nc))
                res.append(comp); n+=1
    return res
